package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Byte-to-redstone bridge: saturates 0..255 into the vanilla 0..15 output range. */
public class ByteToRedstoneDecoderBlock extends PassiveDirectionalSignalBlock{public ByteToRedstoneDecoderBlock(Properties p){super(p);}@Override public MapCodec<ByteToRedstoneDecoderBlock> codec(){return RedstoneEngineering.BYTE_TO_REDSTONE_DECODER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s);if(!DataBusNetwork.valid(l,in))return 0;return Math.min(15,DataBusNetwork.sample(l,in));}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Byte decoder output = "+outputValue(l,p,s)+"/15"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
